use bevy::prelude::{Commands, Entity, Query, Res, ResMut};

use crate::BATTLEFIELD;
use crate::cards;
use crate::effects;
use crate::turns;
use crate::zones;

type StaticCandidates<'w, 's, 'definition, 'owner, 'zone, 'attacking, 'token> = Query<
    'w,
    's,
    (
        Entity,
        &'definition cards::CardDefinition,
        &'owner cards::Owner,
        &'zone zones::InZone,
        Option<&'attacking cards::Attacking>,
        Option<&'token cards::Token>,
    ),
>;

/// 611.3a A continuous effect generated by a static ability isn’t “locked in”; it applies at any given moment to whatever its text indicates.
///
/// # See also
///
/// 611.3. A continuous effect may be generated by the static ability of an object.
///
/// 611.3b The effect applies at all times that the permanent generating it is on the battlefield or the object generating it is in the appropriate zone.
pub fn r611_3a_static_effects(
    mut commands: Commands,
    sources: Query<(
        Entity,
        &cards::CardDefinition,
        &cards::Owner,
        &zones::InZone,
    )>,
    candidates: StaticCandidates<'_, '_, '_, '_, '_, '_, '_>,
    stamped: Query<&effects::SourceTimestamp>,
    applied: Query<(Entity, &effects::ContinuousEffect)>,
    players: Res<turns::TurnOrder>,
    zones: zones::ZoneLookup,
    mut timestamp: ResMut<effects::Timestamp>,
) {
    let players = players.into_inner();
    for (entity, effect) in applied.iter() {
        if effect.until != effects::Duration::WhileSourceOnBattlefield {
            continue;
        }
        let Some(source) = effect.source else {
            continue;
        };
        let Ok((_, source_definition, source_owner, source_zone)) = sources.get(source) else {
            commands.entity(entity).despawn();
            continue;
        };
        if !zones.contains(BATTLEFIELD, **source_zone) {
            commands.entity(entity).despawn();
            continue;
        }
        let still_applies = source_definition.continuous_abilities().any(|ability| {
            ability.change == effect.change
                && ability.filter.kind == effects::FilterKind::Creature
                && candidates.get(effect.affected).is_ok_and(
                    |(_, definition, owner, zone, attacking, token)| {
                        zones.contains(BATTLEFIELD, **zone)
                            && candidate_matches(
                                ability.filter,
                                **source_owner,
                                **owner,
                                attacking.is_some(),
                                token.is_some(),
                                definition,
                                players,
                            )
                    },
                )
        });
        if !still_applies {
            commands.entity(entity).despawn();
        }
    }
    for (source, definition, owner, in_zone) in sources.iter() {
        if definition.continuous_abilities().next().is_none() {
            continue;
        }
        if !zones.contains(BATTLEFIELD, **in_zone) {
            continue;
        }
        let stamp = stamped.get(source).map_or_else(
            |_| {
                let next = timestamp.advance();
                commands.entity(source).insert(effects::SourceTimestamp(next));
                next
            },
            |existing| **existing,
        );
        for ability in definition.continuous_abilities() {
            if ability.filter.kind != effects::FilterKind::Creature {
                continue;
            }
            for (
                candidate,
                candidate_definition,
                candidate_owner,
                candidate_zone,
                attacking,
                token,
            ) in candidates.iter()
            {
                if !zones.contains(BATTLEFIELD, **candidate_zone) {
                    continue;
                }
                if !candidate_matches(
                    ability.filter,
                    **owner,
                    **candidate_owner,
                    attacking.is_some(),
                    token.is_some(),
                    candidate_definition,
                    players,
                ) {
                    continue;
                }
                if already_applied(&applied, source, candidate, ability.change) {
                    continue;
                }
                commands.spawn(effects::ContinuousEffect {
                    affected: candidate,
                    source: Some(source),
                    change: ability.change,
                    until: effects::Duration::WhileSourceOnBattlefield,
                    timestamp: stamp,
                });
            }
        }
    }
}

fn candidate_matches(
    filter: effects::Filter,
    controller: Entity,
    candidate_owner: Entity,
    is_attacking: bool,
    is_token: bool,
    definition: &cards::CardDefinition,
    players: &[Entity],
) -> bool {
    if let Some(controller_ref) = filter.controlled_by
        && !controller_ref.resolve(controller, players).contains(&candidate_owner)
    {
        return false;
    }
    if filter.attacking && !is_attacking {
        return false;
    }
    if filter.nontoken && is_token {
        return false;
    }
    filter.does_creature_match(definition)
}

fn already_applied(
    applied: &Query<(Entity, &effects::ContinuousEffect)>,
    source: Entity,
    affected: Entity,
    change: effects::Change,
) -> bool {
    applied.iter().any(|(_, effect)| {
        effect.source == Some(source)
            && effect.affected == affected
            && effect.change == change
            && effect.until == effects::Duration::WhileSourceOnBattlefield
    })
}

#[cfg(test)]
mod tests {
    use crate::BATTLEFIELD;
    use crate::HAND;
    use crate::cards;
    use crate::effects;
    use crate::mana;
    use crate::testing::*;
    use crate::turns;

    #[test]
    fn always_watching_gives_nontoken_creatures_you_control_vigilance_and_plus_one() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.battlefield([ALWAYS_WATCHING, GRIZZLY_BEARS])
                .hand([RAISE_THE_ALARM])
                .mana_pool(mana![1, W]),
            P2.battlefield([GRIZZLY_BEARS]),
        ]);
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        let [foe] = game.player(p2).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        let [alarm] = game.player(p1).cards_in(HAND).exactly::<1>(RAISE_THE_ALARM)?;
        game.play([p1.cast(alarm).pass_priority(), p2.pass_priority()])?;
        assert_eq!(game.pt(bears), Some(crate::pt!(3, 3)));
        assert!(game.has::<cards::Vigilance>(bears));
        assert_eq!(game.pt(foe), Some(crate::pt!(2, 2)));
        assert!(!game.has::<cards::Vigilance>(foe));
        let soldiers = game.player(p1).cards_in(BATTLEFIELD).exactly::<2>(SOLDIER_TOKEN)?;
        for soldier in soldiers {
            assert_eq!(game.pt(soldier), Some(crate::pt!(1, 1)));
            assert!(!game.has::<cards::Vigilance>(soldier));
        }
        game.play([
            p1.pass_to(turns::Step::DeclareAttackers),
            p2.pass_to(turns::Step::DeclareAttackers),
            p1.declare_attackers([bears]),
        ])?;
        assert!(game.is_attacking(bears));
        assert!(!game.is_tapped(bears));
        Ok(())
    }

    #[test]
    fn always_watching_does_not_affect_opponents_creatures() -> TestResult {
        let (mut game, [_, p2]) = MockGame::new([
            P1.battlefield([ALWAYS_WATCHING]),
            P2.battlefield([GRIZZLY_BEARS]),
        ]);
        let [foe] = game.player(p2).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        game.pass_priority();
        assert_eq!(game.pt(foe), Some(crate::pt!(2, 2)));
        assert!(!game.has::<cards::Vigilance>(foe));
        let affecting = game.with_query::<&effects::ContinuousEffect, usize>(|granted| {
            granted.iter().filter(|effect| effect.affected == foe).count()
        });
        assert_eq!(affecting, 0);
        Ok(())
    }

    #[test]
    fn attacking_creatures_with_test_cover_of_dusk_do_not_tap() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.battlefield([TEST_COVER_OF_DUSK, GRIZZLY_BEARS]),
            P2.battlefield([GRIZZLY_BEARS]),
        ]);
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        game.play([
            p1.pass_to(turns::Step::DeclareAttackers),
            p2.pass_to(turns::Step::DeclareAttackers),
            p1.declare_attackers([bears]),
        ])?;
        assert!(game.is_attacking(bears));
        assert!(!game.is_tapped(bears));
        Ok(())
    }

    #[test]
    fn test_weight_of_command_taps_an_opponents_vigilant_attacker_and_keeps_its_vigilance()
    -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.battlefield([FELIDAR_SOVEREIGN]),
            P2.battlefield([TEST_WEIGHT_OF_COMMAND]),
        ]);
        let [sovereign] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(FELIDAR_SOVEREIGN)?;
        game.play([
            p1.pass_to(turns::Step::DeclareAttackers),
            p2.pass_to(turns::Step::DeclareAttackers),
            p1.declare_attackers([sovereign]),
        ])?;
        assert!(game.is_attacking(sovereign));
        assert!(game.is_tapped(sovereign));
        assert!(game.has::<cards::Vigilance>(sovereign));
        Ok(())
    }

    #[test]
    fn test_night_of_the_hunt_removes_vigilance_so_the_attacker_taps() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.battlefield([FELIDAR_SOVEREIGN]),
            P2.battlefield([TEST_NIGHT_OF_THE_HUNT]),
        ]);
        let [sovereign] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(FELIDAR_SOVEREIGN)?;
        game.pass_priority();
        assert!(!game.has::<cards::Vigilance>(sovereign));
        game.play([
            p1.pass_to(turns::Step::DeclareAttackers),
            p2.pass_to(turns::Step::DeclareAttackers),
            p1.declare_attackers([sovereign]),
        ])?;
        assert!(game.is_attacking(sovereign));
        assert!(game.is_tapped(sovereign));
        Ok(())
    }

    #[test]
    #[ignore = "needs a removal action for enchantments: no fixture destroys a noncreature permanent"]
    fn static_effect_ends_when_its_source_leaves_the_battlefield() -> TestResult {
        let (mut game, [p1, _]) = MockGame::new([
            P1.battlefield([ALWAYS_WATCHING, GRIZZLY_BEARS]),
            P2.battlefield([GRIZZLY_BEARS]),
        ]);
        let [watching] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(ALWAYS_WATCHING)?;
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        game.pass_priority();
        assert!(game.player(p1).cards_in(BATTLEFIELD).has(watching));
        assert_eq!(game.pt(bears), Some(crate::pt!(3, 3)));
        assert!(game.has::<cards::Vigilance>(bears));
        assert_eq!(game.pt(bears), Some(crate::pt!(2, 2)));
        assert!(!game.has::<cards::Vigilance>(bears));
        Ok(())
    }

    #[test]
    fn cover_of_dusk_stops_applying_once_the_creature_stops_attacking() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.battlefield([TEST_COVER_OF_DUSK, GRIZZLY_BEARS]),
            P2.battlefield([GRIZZLY_BEARS]),
        ]);
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        game.play([
            p1.pass_to(turns::Step::DeclareAttackers),
            p2.pass_to(turns::Step::DeclareAttackers),
            p1.declare_attackers([bears]),
        ])?;
        assert!(game.is_attacking(bears));
        let shielding = game.with_query::<&effects::ContinuousEffect, usize>(|granted| {
            granted.iter().filter(|effect| effect.affected == bears).count()
        });
        assert_eq!(shielding, 1);
        game.play([
            p1.pass_to(turns::Step::PostcombatMain),
            p2.pass_to(turns::Step::PostcombatMain),
        ])?;
        assert_eq!(game.turn().step, turns::Step::PostcombatMain);
        assert!(!game.is_attacking(bears));
        let lingering = game.with_query::<&effects::ContinuousEffect, usize>(|granted| {
            granted.iter().filter(|effect| effect.affected == bears).count()
        });
        assert_eq!(lingering, 0);
        Ok(())
    }

    #[test]
    fn later_static_timestamp_wins() -> TestResult {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.battlefield([TEST_COVER_OF_DUSK, GRIZZLY_BEARS]),
            P2.battlefield([TEST_WEIGHT_OF_COMMAND]),
        ]);
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS)?;
        game.play([
            p1.pass_to(turns::Step::DeclareAttackers),
            p2.pass_to(turns::Step::DeclareAttackers),
            p1.declare_attackers([bears]),
        ])?;
        assert!(game.is_attacking(bears));
        assert!(game.is_tapped(bears));
        Ok(())
    }
}
